import csv,sys,os,collections,sqlite3,unicodedata
T='scratchpad/session_2026-11-06-base-vocabulary-review/terminology-pass'
def rd(p):
    with open(p,newline='',encoding='utf-8') as f: return list(csv.reader(f,delimiter='\t'))
def col(h,*keys,excl=()):
    for i,x in enumerate(h):
        xl=x.lower()
        if any(k in xl for k in keys) and not any(e in xl for e in excl): return i
    raise SystemExit(f'no col {keys} in {h}')
pairs=sorted(d for d in os.listdir(T) if os.path.isfile(f'{T}/{d}/pass-record.md'))
allobs=set(); allrh=set(); rows=[]
for p in pairs:
    c=rd(f'{T}/{p}/coverage.tsv'); h=c[0]; si=col(h,'status')
    st=collections.Counter(r[si].split(' ')[0] for r in c[1:] if len(r)>si)
    o=rd(f'{T}/{p}/observations.tsv'); oh=o[0]; pi=col(oh,'phrase_verbatim'); li=col(oh,'language')
    ci=col(oh,'concept',excl=('label',)) 
    rh=rd(f'{T}/{p}/reverse-harvest.tsv'); rhh=rh[0]; rpi=col(rhh,'phrase')
    op={r[pi].strip() for r in o[1:] if len(r)>pi}
    rp={r[rpi].strip() for r in rh[1:] if len(r)>rpi}
    lang=p.split('-')[0].lower() if p!='EN-VARIANTS' else 'en'
    for x in op: allobs.add((lang,x))
    for x in rp: allrh.add((lang,x))
    # forms per concept
    fc=collections.defaultdict(set)
    for r in o[1:]:
        if len(r)>pi:
            for k in r[ci].split('|'): fc[k.strip()].add(r[pi].strip())
    multi=sum(1 for k,v in fc.items() if len(v)>=2)
    rows.append((p,len(c)-1,dict(st),len(o)-1,len(op),len(rh)-1,len(rp),len(fc),multi))
for r in rows: print(*r,sep='\t')
print('distinct (lang,phrase) obs',len(allobs),'rh',len(allrh),'rh-only',len(allrh-allobs),'union',len(allobs|allrh))
con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
al=collections.defaultdict(set)
for a,l in con.execute('select alias,language from term_aliases'):
    if a and l: al[l.lower().split('-')[0].split('_')[0]].add(unicodedata.normalize('NFC',a).casefold().strip())
canon={unicodedata.normalize('NFC',t).casefold() for (t,) in con.execute('select canonical_en from terms') if t}
hit=[(l,x) for l,x in allobs|allrh if unicodedata.normalize('NFC',x).casefold() in al.get(l,set())]
hitc=[(l,x) for l,x in allobs|allrh if l=='en' and x.casefold() in canon]
print('exact casefold match to held alias same language',len(hit)); print(sorted(hit))
print('en phrases equal to a canonical_en',len(hitc),sorted(hitc))
print('alias languages',{k:len(v) for k,v in al.items()})
